1	<title>Portal Redesign — Shell</title>
2	<link rel="preconnect" href="https://fonts.googleapis.com">
3	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
4	<link href="https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
5	
6	<style>
7	  :root{
8	    --bg: #05060d;
9	    --surface-1: #0c0f1c;
10	    --surface-2: #10142450;
11	    --border: rgba(255,255,255,0.07);
12	    --border-strong: rgba(255,255,255,0.14);
13	    --text: #f4f5fb;
14	    --text-muted: #97a1c4;
15	    --text-faint: #5b6488;
16	    --brand: #6f47f5;
17	    --brand-light: #a48bff;
18	    --cyan: #22d3ee;
19	    --blue: #3b82f6;
20	    --good: #34d399;
21	    --warn: #fbbf24;
22	    --bad: #f87171;
23	    --font-display: "Sora", "Inter", system-ui, sans-serif;
24	    --font-body: "Inter", system-ui, sans-serif;
25	  }
26	
27	  *{ box-sizing:border-box; }
28	  body{
29	    margin:0; background:var(--bg); color:var(--text); font-family:var(--font-body);
30	    -webkit-font-smoothing:antialiased; min-height:100vh; overflow-x:hidden;
31	  }
32	  .app{ display:flex; min-height:100vh; }
33	
34	  /* ================= sidebar ================= */
35	  .sidebar{
36	    width:264px; flex-shrink:0; background:var(--surface-1); border-right:1px solid var(--border);
37	    display:flex; flex-direction:column; padding:20px 14px; position:sticky; top:0; height:100vh;
38	  }
39	  .brand-row{ display:flex; align-items:center; gap:10px; padding:6px 8px 22px; }
40	  .brand-row .mark{
41	    width:32px; height:32px; border-radius:10px; flex-shrink:0;
42	    background:linear-gradient(135deg,var(--brand-light),var(--brand));
43	    display:flex; align-items:center; justify-content:center;
44	    font-family:var(--font-display); font-weight:800; font-size:15px; color:#0a0714;
45	    box-shadow:0 6px 18px -6px rgba(111,71,245,0.6);
46	  }
47	  .brand-row .name{ font-family:var(--font-display); font-weight:700; font-size:15.5px; letter-spacing:.01em; }
48	
49	  .nav-scroll{ flex:1; overflow-y:auto; }
50	  .nav-group{ margin-bottom:18px; }
51	  .nav-group-label{ font-size:10.5px; font-weight:700; letter-spacing:.11em; color:var(--text-faint); padding:0 10px 8px; text-transform:uppercase; }
52	  .nav-item{
53	    position:relative; display:flex; align-items:center; gap:11px; padding:9px 10px; border-radius:11px;
54	    color:var(--text-muted); font-size:13.5px; font-weight:500; cursor:pointer; margin-bottom:2px;
55	    transition:color .15s ease, background .15s ease;
56	  }
57	  .nav-item svg{ width:18px; height:18px; flex-shrink:0; opacity:.85; }
58	  .nav-item:hover{ color:var(--text); background:rgba(255,255,255,0.035); }
59	  .nav-item.active{ color:var(--text); }
60	  .nav-item.active::before{
61	    content:""; position:absolute; inset:0; border-radius:11px;
62	    background:linear-gradient(135deg, rgba(111,71,245,0.22), rgba(34,211,238,0.08));
63	    border:1px solid rgba(164,139,255,0.35);
64	    box-shadow:0 4px 18px -6px rgba(111,71,245,0.5);
65	  }
66	  .nav-item.active svg, .nav-item.active .label{ position:relative; opacity:1; }
67	  .nav-item .tag{
68	    margin-left:auto; font-size:9.5px; font-weight:700; padding:2px 6px; border-radius:999px; position:relative;
69	    background:rgba(52,211,153,0.15); color:#6ee7b3; letter-spacing:.03em;
70	  }
71	
72	  .sidebar-foot{ border-top:1px solid var(--border); padding-top:12px; margin-top:6px; }
73	  .acct-card{ display:flex; align-items:center; gap:10px; padding:8px; border-radius:12px; cursor:pointer; transition:background .15s ease; }
74	  .acct-card:hover{ background:rgba(255,255,255,0.035); }
75	  .acct-avatar{ width:32px; height:32px; border-radius:9px; background:linear-gradient(135deg,var(--cyan),var(--blue)); flex-shrink:0; display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:700; font-size:12.5px; color:#03131a; }
76	  .acct-meta{ min-width:0; }
77	  .acct-name{ font-size:13px; font-weight:600; color:var(--text); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
78	  .acct-plan{ font-size:11px; color:var(--text-faint); }
79	
80	  /* ================= main ================= */
81	  .main{ flex:1; min-width:0; }
82	  .topbar{
83	    display:flex; align-items:center; gap:14px; padding:16px 32px; border-bottom:1px solid var(--border);
84	    position:sticky; top:0; background:rgba(5,6,13,0.72); backdrop-filter:blur(14px); z-index:5;
85	  }
86	  .search{
87	    flex:1; max-width:420px; display:flex; align-items:center; gap:9px; background:rgba(255,255,255,0.04);
88	    border:1px solid var(--border); border-radius:11px; padding:9px 13px; color:var(--text-faint); font-size:13px;
89	  }
90	  .search svg{ width:15px; height:15px; flex-shrink:0; }
91	  .topbar-right{ margin-left:auto; display:flex; align-items:center; gap:10px; }
92	  .icon-btn{
93	    width:36px; height:36px; border-radius:10px; border:1px solid var(--border); background:rgba(255,255,255,0.03);
94	    display:flex; align-items:center; justify-content:center; color:var(--text-muted); cursor:pointer; position:relative;
95	    transition:border-color .15s ease, color .15s ease;
96	  }
97	  .icon-btn:hover{ border-color:var(--border-strong); color:var(--text); }
98	  .icon-btn svg{ width:17px; height:17px; }
99	  .icon-btn .dot{ position:absolute; top:7px; right:7px; width:6px; height:6px; border-radius:999px; background:var(--brand-light); box-shadow:0 0 6px var(--brand-light); }
100	  .deploy-btn{
101	    display:inline-flex; align-items:center; gap:7px; background:linear-gradient(135deg,var(--brand-light),var(--brand));
102	    color:#0a0714; font-weight:700; font-size:13px; border:none; border-radius:11px; padding:10px 16px; cursor:pointer;
103	    box-shadow:0 10px 24px -10px rgba(111,71,245,0.7); transition:transform .15s ease;
104	  }
105	  .deploy-btn:hover{ transform:translateY(-1px); }
106	  .deploy-btn svg{ width:15px; height:15px; }
107	
108	  .content{ padding:30px 32px 60px; max-width:1240px; }
109	
110	  /* hero */
111	  .hero{
112	    position:relative; border-radius:22px; padding:34px 32px; margin-bottom:26px; overflow:hidden;
113	    background:var(--surface-1); border:1px solid var(--border);
114	  }
115	  .hero canvas{ position:absolute; inset:0; width:100%; height:100%; opacity:.55; }
116	  .hero-inner{ position:relative; z-index:1; display:flex; align-items:center; justify-content:space-between; gap:24px; flex-wrap:wrap; }
117	  .hero h1{ font-family:var(--font-display); font-size:25px; font-weight:700; margin:0 0 7px; }
118	  .hero h1 span{ background:linear-gradient(90deg,var(--brand-light),var(--cyan)); -webkit-background-clip:text; background-clip:text; color:transparent; }
119	  .hero p{ margin:0; color:var(--text-muted); font-size:13.5px; max-width:46ch; line-height:1.55; }
120	  .hero-actions{ display:flex; gap:10px; }
121	  .btn-ghost{
122	    display:inline-flex; align-items:center; gap:7px; background:rgba(255,255,255,0.05); border:1px solid var(--border-strong);
123	    color:var(--text); font-weight:600; font-size:13px; border-radius:11px; padding:10px 16px; cursor:pointer;
124	  }
125	
126	  /* stat grid */
127	  .stats{ display:grid; grid-template-columns:repeat(4,1fr); gap:14px; margin-bottom:26px; }
128	  @media (max-width:900px){ .stats{ grid-template-columns:repeat(2,1fr); } }
129	  .stat-card{
130	    background:var(--surface-1); border:1px solid var(--border); border-radius:16px; padding:18px;
131	    opacity:0; transform:translateY(8px); animation:cardIn .5s cubic-bezier(.2,.7,.3,1) forwards;
132	  }
133	  .stat-card:nth-child(1){ animation-delay:.04s; } .stat-card:nth-child(2){ animation-delay:.1s; }
134	  .stat-card:nth-child(3){ animation-delay:.16s; } .stat-card:nth-child(4){ animation-delay:.22s; }
135	  @keyframes cardIn{ to{ opacity:1; transform:translateY(0); } }
136	  .stat-top{ display:flex; align-items:center; justify-content:space-between; margin-bottom:14px; }
137	  .stat-icon{ width:34px; height:34px; border-radius:10px; display:flex; align-items:center; justify-content:center; }
138	  .stat-icon svg{ width:17px; height:17px; }
139	  .stat-icon.violet{ background:rgba(111,71,245,0.16); color:var(--brand-light); }
140	  .stat-icon.cyan{ background:rgba(34,211,238,0.14); color:var(--cyan); }
141	  .stat-icon.green{ background:rgba(52,211,153,0.14); color:var(--good); }
142	  .stat-icon.blue{ background:rgba(59,130,246,0.14); color:var(--blue); }
143	  .stat-trend{ font-size:11px; font-weight:700; display:flex; align-items:center; gap:3px; }
144	  .stat-trend.up{ color:var(--good); } .stat-trend.down{ color:var(--bad); }
145	  .stat-val{ font-family:var(--font-display); font-size:24px; font-weight:700; line-height:1; margin-bottom:5px; }
146	  .stat-label{ font-size:12px; color:var(--text-faint); }
147	
148	  /* two column */
149	  .cols{ display:grid; grid-template-columns:1.6fr 1fr; gap:18px; }
150	  @media (max-width:900px){ .cols{ grid-template-columns:1fr; } }
151	  .panel{ background:var(--surface-1); border:1px solid var(--border); border-radius:18px; padding:20px 22px; }
152	  .panel-head{ display:flex; align-items:center; justify-content:space-between; margin-bottom:16px; }
153	  .panel-title{ font-family:var(--font-display); font-size:15px; font-weight:700; }
154	  .panel-link{ font-size:12px; color:var(--brand-light); font-weight:600; cursor:pointer; }
155	
156	  .activity-row{ display:flex; align-items:center; gap:12px; padding:11px 0; border-bottom:1px solid var(--border); }
157	  .activity-row:last-child{ border-bottom:none; }
158	  .activity-icon{ width:32px; height:32px; border-radius:9px; background:rgba(255,255,255,0.04); border:1px solid var(--border); display:flex; align-items:center; justify-content:center; flex-shrink:0; }
159	  .activity-icon svg{ width:15px; height:15px; color:var(--text-muted); }
160	  .activity-icon.ok svg{ color:var(--good); } .activity-icon.warn svg{ color:var(--warn); }
161	  .activity-text{ font-size:13px; color:var(--text); }
162	  .activity-text b{ font-weight:600; }
163	  .activity-time{ font-size:11.5px; color:var(--text-faint); margin-left:auto; flex-shrink:0; }
164	
165	  .qa-item{ display:flex; align-items:center; gap:11px; padding:10px 11px; border-radius:12px; border:1px solid var(--border); margin-bottom:9px; cursor:pointer; transition:border-color .15s ease, background .15s ease; }
166	  .qa-item:hover{ border-color:var(--border-strong); background:rgba(255,255,255,0.02); }
167	  .qa-item svg{ width:16px; height:16px; color:var(--brand-light); flex-shrink:0; }
168	  .qa-item span{ font-size:12.5px; font-weight:600; }
169	  .qa-item .chev{ margin-left:auto; color:var(--text-faint); width:14px; height:14px; }
170	
171	  .balance-box{ margin-top:6px; padding:16px; border-radius:14px; background:linear-gradient(160deg, rgba(111,71,245,0.14), rgba(34,211,238,0.05)); border:1px solid rgba(164,139,255,0.25); }
172	  .balance-label{ font-size:11px; color:var(--text-muted); margin-bottom:4px; }
173	  .balance-val{ font-family:var(--font-display); font-size:21px; font-weight:700; margin-bottom:10px; }
174	  .balance-btn{ width:100%; background:rgba(255,255,255,0.08); border:1px solid var(--border-strong); color:var(--text); font-size:12px; font-weight:600; border-radius:9px; padding:8px; cursor:pointer; }
175	
176	  ::-webkit-scrollbar{ width:8px; height:8px; }
177	  ::-webkit-scrollbar-thumb{ background:rgba(255,255,255,0.08); border-radius:99px; }
178	</style>
179	
180	<div class="app">
181	  <aside class="sidebar">
182	    <div class="brand-row">
183	      <div class="mark">N</div>
184	      <div class="name">NXEON</div>
185	    </div>
186	
187	    <div class="nav-scroll">
188	      <div class="nav-group">
189	        <div class="nav-item active" data-icon="grid"><span class="label">Overview</span></div>
190	      </div>
191	
192	      <div class="nav-group">
193	        <div class="nav-group-label">Infrastructure</div>
194	        <div class="nav-item" data-icon="server"><span class="label">Servers</span></div>
195	        <div class="nav-item" data-icon="globe"><span class="label">Shared hosting</span></div>
196	        <div class="nav-item" data-icon="controller"><span class="label">Game servers</span></div>
197	        <div class="nav-item" data-icon="stack"><span class="label">Volumes</span></div>
198	      </div>
199	
200	      <div class="nav-group">
201	        <div class="nav-group-label">Grow</div>
202	        <div class="nav-item" data-icon="domain"><span class="label">Domains</span></div>
203	        <div class="nav-item" data-icon="mail"><span class="label">Mail</span></div>
204	        <div class="nav-item" data-icon="shield"><span class="label">SSL</span></div>
205	        <div class="nav-item" data-icon="share"><span class="label">Refer & earn</span><span class="tag">NEW</span></div>
206	      </div>
207	
208	      <div class="nav-group">
209	        <div class="nav-group-label">Build</div>
210	        <div class="nav-item" data-icon="spark"><span class="label">Build with AI</span></div>
211	        <div class="nav-item" data-icon="matrix"><span class="label">Matrix</span></div>
