220	        <div class="nav-item" data-icon="gear"><span class="label">Settings</span></div>
221	      </div>
222	    </div>
223	
224	    <div class="sidebar-foot">
225	      <div class="acct-card">
226	        <div class="acct-avatar">JD</div>
227	        <div class="acct-meta">
228	          <div class="acct-name">Jordan Diaz</div>
229	          <div class="acct-plan">Pro account</div>
230	        </div>
231	      </div>
232	    </div>
233	  </aside>
234	
235	  <div class="main">
236	    <div class="topbar">
237	      <div class="search"><svg data-icon="search"></svg><span>Search servers, domains, invoices…</span></div>
238	      <div class="topbar-right">
239	        <button class="icon-btn"><svg data-icon="bell"></svg><span class="dot"></span></button>
240	        <button class="deploy-btn"><svg data-icon="plus"></svg>Deploy</button>
241	      </div>
