243	
244	    <div class="content">
245	      <div class="hero">
246	        <canvas id="heroCanvas"></canvas>
247	        <div class="hero-inner">
248	          <div>
249	            <h1>Welcome back, <span>Jordan</span></h1>
250	            <p>3 servers running smoothly. Your wallet balance covers the next 18 days of usage at current spend.</p>
251	          </div>
252	          <div class="hero-actions">
253	            <button class="btn-ghost"><svg data-icon="wallet" style="width:15px;height:15px"></svg>Add funds</button>
254	            <button class="deploy-btn"><svg data-icon="plus"></svg>Deploy a server</button>
255	          </div>
256	        </div>
