259	      <div class="stats">
260	        <div class="stat-card">
261	          <div class="stat-top"><div class="stat-icon violet"><svg data-icon="server"></svg></div><div class="stat-trend up">+1 <svg style="width:10px;height:10px" data-icon="arrowup"></svg></div></div>
262	          <div class="stat-val">3</div>
263	          <div class="stat-label">Active servers</div>
264	        </div>
265	        <div class="stat-card">
266	          <div class="stat-top"><div class="stat-icon green"><svg data-icon="pulse"></svg></div></div>
