288	            <div class="activity-time">2h ago</div>
289	          </div>
290	          <div class="activity-row">
291	            <div class="activity-icon"><svg data-icon="wallet"></svg></div>
292	            <div class="activity-text">Auto-recharge added <b>$25.00</b> to your wallet</div>
293	            <div class="activity-time">1d ago</div>
294	          </div>
295	          <div class="activity-row">
296	            <div class="activity-icon warn"><svg data-icon="alert"></svg></div>
297	            <div class="activity-text">Backup for <b>minecraft-mm8w85</b> is 2 days overdue</div>
298	            <div class="activity-time">2d ago</div>
299	          </div>
