import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

// Brand typeface, loaded once site-wide and self-hosted by next/font (no CDN at
// runtime). Exposed as CSS variables that globals.css maps onto Tailwind's
// --font-sans / --font-mono, so every page + the dashboard share one typeface
// instead of the browser default. Geist Mono backs the terminal/code surfaces.
const geistSans = Geist({ subsets: ["latin"], variable: "--font-geist-sans", display: "swap" });
const geistMono = Geist_Mono({ subsets: ["latin"], variable: "--font-geist-mono", display: "swap" });
import { Analytics } from "@/components/marketing/Analytics";
import { TrackingProvider } from "@/components/marketing/TrackingProvider";
import MetaPixelTracker from "@/components/marketing/MetaPixelTracker";
import { OrganizationJsonLd } from "@/components/marketing/StructuredData";
import CookieConsent from "@/components/marketing/CookieConsent";
import LiveChat from "@/components/marketing/LiveChat";
import ChatWidget from "@/components/ChatWidget";
import { SandboxBanner } from "@/components/SandboxBanner";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
const DESCRIPTION =
  "High-performance NVMe VPS hosting with instant deployment — control panels, game servers, VPNs, and domains. Deploy a server in seconds with full root access and a dedicated IP option.";

/**
 * Root metadata. A function, not a constant, because the platform name comes from
 * Settings → General (`brand_name`) — every string below used to hardcode "Nxeon", so
 * renaming the platform in the admin panel changed the browser tab, the per-page title
 * template, the Open Graph site name and the author/creator/publisher meta tags on exactly
 * nothing. Next.js only awaits a DB read here if the export is `generateMetadata`.
 *
 * Still hardcoded and out of scope for this pass: the schema.org JSON-LD in
 * components/marketing/StructuredData.tsx (Organization, Product, BlogPosting).
 *
 * Failure of the settings read is non-fatal on purpose and mirrors the `livechat_snippet`
 * read below: if Postgres is unreachable, the correct outcome is a page that renders with
 * the default title, not a 500 on the root layout that takes the whole site (including
 * /status) down with it.
 */
export async function generateMetadata(): Promise<Metadata> {
  // Only used when @/lib/settings cannot even be loaded. Kept a local literal rather
  // than a static SETTINGS_DEFAULTS import so the root layout still has no top-level
  // dependency on Prisma — the same reason the livechat read below is a dynamic import.
  let brand = "Nxeon";
  let fbDomainVerify = "";
  try {
    const { getSetting, SETTINGS_DEFAULTS } = await import("@/lib/settings");
    brand = (await getSetting("brand_name")).trim() || SETTINGS_DEFAULTS.brand_name;
    fbDomainVerify = (await getSetting("meta_domain_verification")).trim();
  } catch {
    /* settings unavailable — fall back to the built-in brand name */
  }
  return {
    metadataBase: new URL(APP_URL),
    // Meta Business domain verification — emits <meta name="facebook-domain-verification">
    // only when an operator has set the token in admin → Marketing → Tracking.
    ...(fbDomainVerify
      ? { verification: { other: { "facebook-domain-verification": fbDomainVerify } } }
      : {}),
    title: {
      default: `${brand} — Cloud VPS Hosting, Game Servers & Domains`,
      template: `%s — ${brand}`,
    },
    description: DESCRIPTION,
    applicationName: brand,
    keywords: [
      "VPS hosting",
      "cloud VPS",
      "game server hosting",
      "Minecraft server hosting",
      "NVMe VPS",
      "affordable VPS",
      "domain registration",
      "dedicated IP",
      "Singapore VPS",
      "cPanel hosting",
    ],
    authors: [{ name: brand }],
    creator: brand,
    publisher: brand,
    alternates: { canonical: "/" },
    openGraph: {
      type: "website",
      siteName: brand,
      url: APP_URL,
      locale: "en_US",
    },
    twitter: {
      card: "summary_large_image",
    },
    robots: {
      index: true,
      follow: true,
      googleBot: {
        index: true,
        follow: true,
        "max-image-preview": "large",
        "max-snippet": -1,
        "max-video-preview": -1,
      },
    },
    icons: {
      icon: [
        { url: "/favicon.ico", sizes: "any" },
        { url: "/icon-192.png", sizes: "192x192", type: "image/png" },
        { url: "/icon-512.png", sizes: "512x512", type: "image/png" },
      ],
      shortcut: "/favicon.ico",
      apple: "/apple-touch-icon.png",
    },
    manifest: "/manifest.webmanifest",
  };
}

export default async function RootLayout({ children }: { children: React.ReactNode }) {
  // Admin-configured live-chat snippet (trusted input — only staff can set it).
  let chatSnippet = "";
  try {
    const { getSetting } = await import("@/lib/settings");
    chatSnippet = (await getSetting("livechat_snippet", "")) ?? "";
  } catch {
    /* settings unavailable — chat stays off */
  }

  // Signed-in viewer (if any) so the chat widget prefills name/email and doesn't
  // re-ask; anonymous visitors are required to provide them. Best-effort.
  let chatViewer: { name: string | null; email: string | null } | null = null;
  try {
    const { currentUser } = await import("@/lib/auth");
    const u = await currentUser();
    if (u) chatViewer = { name: u.name ?? null, email: u.email ?? null };
  } catch {
    /* not signed in / auth unavailable — widget will ask for details */
  }
  return (
    <html lang="en" className={`${geistSans.variable} ${geistMono.variable}`}>
      <body>
        <SandboxBanner />
        {children}
