import type { Metadata } from "next";
import { Geist, Geist_Mono, Sora, Inter } from "next/font/google";
import "./globals.css";

// Brand typeface, loaded once site-wide and self-hosted by next/font (no CDN at
// runtime). Exposed as CSS variables that globals.css maps onto Tailwind's
// --font-sans / --font-mono, so every page + the dashboard share one typeface
// instead of the browser default. Geist Mono backs the terminal/code surfaces.
const geistSans = Geist({ subsets: ["latin"], variable: "--font-geist-sans", display: "swap" });
const geistMono = Geist_Mono({ subsets: ["latin"], variable: "--font-geist-mono", display: "swap" });

// Portal-v2 redesign typeface pair (Sora display / Inter body), approved in the
// 2026-09 mockups (scratchpad/portal-redesign-*.html). Loaded here once,
// site-wide, self-hosted like Geist above — rather than per-page — so only one
// next/font fetch ever happens no matter how many redesigned pages opt in.
// This does NOT change the site's default typeface: geistSans stays the
// `font-sans` body{} uses in globals.css. These are exposed as
// --font-portal-sora/-inter and mapped onto the `font-pv-display` /
// `font-pv-body` Tailwind utilities (see globals.css's @theme block), so
// redesigned components opt in explicitly instead of it leaking site-wide.
const portalSora = Sora({ subsets: ["latin"], variable: "--font-portal-sora", display: "swap" });
const portalInter = Inter({ subsets: ["latin"], variable: "--font-portal-inter", display: "swap" });

--color-accent-blue: #3b82f6;
--color-accent-cyan: #22d3ee;

/* ── Portal v2 redesign tokens ──────────────────────────────────────────
   New, parallel design system for the from-scratch customer-portal
   redesign (approved mockups: scratchpad/portal-redesign-{shell,wizard,
   billing,server}.html — 2026-09). These are ADDITIVE: every brand hue
   above (brand-*/navy-*/accent-*) stays exactly as-is because ~54
   unredesigned pages still reference it directly. `pv` = "portal v2".
   Colors are deliberately close to but distinct from the brand-* scale —
   they're the exact literal values from the approved mockups, not a
   re-derivation, so pages built against these tokens match the approved
   screens pixel-for-pixel. Consumers get free Tailwind utilities from
   these (bg-pv-surface-1, text-pv-text-muted, font-pv-display,
   rounded-pv-lg, etc.) since Tailwind v4 auto-generates a utility for
   every @theme custom property in a recognized namespace. */
--color-pv-bg: #05060d;
--color-pv-surface-1: #0c0f1c;
/* Rarely-used tertiary/glass layer from the shell mockup's palette
   (defined there as #10142450 — solid hex + ~31% alpha baked in). Use
   bg-pv-surface-2/30 to reproduce that exact translucency instead of
   baking alpha into the token, so any opacity can be dialed per use. */
--color-pv-surface-2: #101424;
--color-pv-text: #f4f5fb;
--color-pv-text-muted: #97a1c4;
--color-pv-text-faint: #5b6488;
/* Brand violet, same hue as --color-brand-500 (#6f47f5) — kept as its own
   token because every mockup treats "brand" and "brand-light" as a
   specific two-stop gradient pair, not the brand-* 50-900 ramp. */
--color-pv-brand: #6f47f5;
--color-pv-brand-light: #a48bff;
--color-pv-cyan: #22d3ee;
--color-pv-blue: #3b82f6;
--color-pv-good: #34d399;
--color-pv-warn: #fbbf24;
--color-pv-bad: #f87171;

/* Radius scale used across the mockups (nav pills/chips, panels, hero/
   wizard-shell containers) — none of these line up with Tailwind's
   built-in rounded-* steps closely enough to reuse them without visibly
   drifting off the approved screens. */
--radius-pv-sm: 10px;
--radius-pv-md: 14px;
--radius-pv-lg: 18px;
--radius-pv-xl: 22px;

/* Sora (display/headings) + Inter (body) — the mockups' typeface pair,
   loaded via next/font/google in app/layout.tsx (portalSora/portalInter)
   and referenced here by their CSS var names. Falls back gracefully if
   the font vars are ever unavailable (e.g. this stylesheet reused
   somewhere the root layout didn't mount). Opt-in only: body{}'s
   `font-sans` default (Geist) is untouched. */
--font-pv-display: var(--font-portal-sora), "Sora", ui-sans-serif, system-ui, sans-serif;
--font-pv-body: var(--font-portal-inter), "Inter", ui-sans-serif, system-ui, sans-serif;

--animate-fade-up: fade-up 0.4s ease-out both;

  @keyframes ring-glow {
    0%, 100% { opacity: 0.5; }
    50% { opacity: 1; }
  }

  /* Portal v2 stat-card entrance (shell mockup: cards fade/slide up on load,
     staggered ~60ms apart via an inline animation-delay at the call site —
     e.g. `className="animate-pv-card-in [animation-delay:120ms]"`). One-shot;
     resting state is fully visible, so reduced-motion users never see a
     stuck-invisible card. */
  --animate-pv-card-in: pv-card-in 0.5s cubic-bezier(0.2, 0.7, 0.3, 1) both;
  @keyframes pv-card-in {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
  }
}

