/* ── Portal v2 redesign — shared utilities (foundation layer) ────────────────
   Companion to the @theme tokens above. Only the two effects every one of the
   four approved mockups leans on as a *background/nav treatment* (not a
   one-off component style — those live as React components in
   components/portal-v2/primitives.tsx) get a reusable class here: the ambient
   drifting gradient-mesh page background, and the floating-glow active-nav
   pill. Everything else (cards, stat tiles, gauges) is a component, not a
   global class, because it needs props (tone, value) a CSS class can't take.
   Nothing in this block touches .card/.btn-*/.glass or any selector an
   existing page depends on — it's purely new `.pv-*`-prefixed surface. */
@layer components {
  /* Base surface used by components/portal-v2/primitives.tsx's <Surface>.
     Kept here (rather than only inline in the component) so any hand-written
     markup that needs the exact same treatment before the component library
     covers it can apply one class instead of restating the shadow stack. */
  .pv-surface {
    @apply rounded-pv-lg border border-white/[0.07] bg-pv-surface-1;
    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
  }
  /* "Raised" variant — the wizard's sticky order-summary rail and the
     billing cockpit header sit a hair above the base surface: a stronger
     border and an added soft brand-glow, not just a darker fill. */
  .pv-surface-elevated {
    @apply rounded-pv-lg border border-white/[0.14] bg-pv-surface-1;
    box-shadow:
      0 1px 0 0 rgb(255 255 255 / 0.04) inset,
      0 12px 36px -14px rgb(0 0 0 / 0.55),
      0 0 46px -22px rgb(111 71 245 / 0.35);
  }

  /* Ambient slow-drifting gradient-mesh background (shell mockup's canvas
     hero, reimplemented as pure CSS so any page can opt in with one class
     instead of mounting a <canvas> + rAF loop). Apply to a `position:
     relative` ancestor — e.g. `<div className="pv-ambient relative ...">` —
     the mesh paints behind that element's content via an absolutely
     positioned ::before at z-index:-1, oversized (inset:-20%) so the drift
     animation never exposes a hard edge. Three radial blobs at the exact
     brand/cyan/blue opacities the approved shell mockup used. */
  .pv-ambient {
    position: relative;
    isolation: isolate;
  }
  .pv-ambient::before {
    content: "";
    position: absolute;
    inset: -20%;
    z-index: -1;
    pointer-events: none;
    background-image:
      radial-gradient(closest-side, rgb(111 71 245 / 0.35), transparent),
      radial-gradient(closest-side, rgb(34 211 238 / 0.22), transparent),
      radial-gradient(closest-side, rgb(59 130 246 / 0.18), transparent);
    background-repeat: no-repeat;
    background-size: 55% 55%, 45% 45%, 40% 40%;
    background-position: 12% 20%, 85% 55%, 45% 92%;
    filter: blur(48px);
    animation: pv-drift 22s ease-in-out infinite alternate;
  }
  @keyframes pv-drift {
    0% { transform: translate3d(0, 0, 0) scale(1); }
    50% { transform: translate3d(-3%, 3%, 0) scale(1.06); }
    100% { transform: translate3d(3%, -2%, 0) scale(1); }
  }
  @media (prefers-reduced-motion: reduce) {
    .pv-ambient::before { animation: none; }
  }

  /* Floating-glow active nav item (shell mockup's `.nav-item.active`). Put
     `.pv-nav-item` on every item and add `.pv-nav-item-active` only to the
     current one — the glow pill is a ::before so it can fade/slide
     independently of the label/icon opacity above it. `position: relative`
     is required on the item for the ::before to place correctly. */
  .pv-nav-item {
    @apply relative flex items-center gap-3 rounded-pv-sm px-2.5 py-2 text-[13.5px] font-medium text-pv-text-muted transition-colors duration-150;
  }
  .pv-nav-item:hover {
    @apply text-pv-text;
    background: rgb(255 255 255 / 0.035);
  }
  .pv-nav-item-active {
    @apply text-pv-text;
  }
  .pv-nav-item-active::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: linear-gradient(135deg, rgb(111 71 245 / 0.22), rgb(34 211 238 / 0.08));
    border: 1px solid rgb(164 139 255 / 0.35);
    box-shadow: 0 4px 18px -6px rgb(111 71 245 / 0.5);
  }
  /* Item content sits above the glow pseudo-element. */
  .pv-nav-item > * {
    position: relative;
  }
}

