import type { SVGProps } from "react";

/**
 * Portal v2 icon set — hand-drawn 24x24 stroke icons, pulled verbatim from the
 * approved redesign mockups (scratchpad/portal-redesign-{shell,wizard,server}.html,
 * 2026-09). This continues the codebase's existing convention (there is no icon
 * library anywhere — see components/portal/Shell.tsx's `icons` map) rather than
 * introducing a foreign one. Do NOT add new glyphs here by inventing path data —
 * every shape below is copied from an already-approved mockup. If a redesigned
 * page needs an icon that isn't here, pull it from the relevant mockup file
 * first (or get a new one approved), then add it the same way.
 *
 * Each export is a plain function component so unused ones tree-shake normally.
 * Defaults match the mockups' rendering: viewBox 0 0 24 24, stroke="currentColor",
 * strokeWidth 1.8, round caps/joins. Override size via width/height/className;
 * override color via the parent's `color`/`text-*` class (all shapes use
 * currentColor, no hardcoded fills except the small solid dots noted inline).
 */

type IconProps = SVGProps<SVGSVGElement>;

function makeIcon(displayName: string, paths: React.ReactNode) {
  function IconCmp({ className, ...props }: IconProps) {
    return (
      <svg
        viewBox="0 0 24 24"
        width={24}
        height={24}
        fill="none"
        stroke="currentColor"
        strokeWidth={1.8}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={className}
        {...props}
      >
        {paths}
      </svg>
    );
  }
  IconCmp.displayName = displayName;
  return IconCmp;
}

